class AttestationAccessGrantStateItem(BaseModel):
    """One grant's public view plus its expiry and state at ``checked_at``.

    The first four members are exactly the existing grant public view;
    ``expires_at`` is the scheduled UTC expiry instant (null when no expiry
    was ever scheduled) and ``state`` is one of ``revoked``, ``expired``,
    ``scheduled``, or ``active``.

    def __init__(self, reason: str):
        super().__init__(details={"reason": reason})


class AttestationAccessGrantExpiryConflictError(DomainError):
    """A second, different expiry for a grant that already has one.

    A grant carries at most one immutable expiry: a submission carrying an
    ``expires_at`` different from the grant's existing scheduled expiry is a
    conflict, not a replacement, and writes neither an expiry nor an audit
    event. A retry carrying the same ``expires_at`` is instead the normal
    200 idempotent return of the original record.
    """

    status_code = 409
    code = "attestation_access_grant_expiry_conflict"
    message = (
        "The grant already has a scheduled expiry with a different expires_at."
    )

    def __init__(self, grant_id: str):
        super().__init__(details={"grant_id": grant_id})


class ProtectedResourceNotFoundError(DomainError):
    """Opaque 404 for the protected read route.

    A missing attestation, an unauthenticated caller, and an unauthorized
    caller all render identically so resource existence is never revealed
    to a caller without access.
    """

    status_code = 404
    code = "not_found"
    message = "The requested resource does not exist."

    def __init__(self) -> None:
        super().__init__()


class LineageValidationError(DomainError):
    """A malformed lineage query (``direction`` / ``max_depth``).

    Renders with the same ``validation_error`` code and issue-shaped details
    as request-body validation failures.
    """

    status_code = 422
    code = "validation_error"
    message = "Request payload failed validation."

    def __init__(self, issues: list[dict]):
        super().__init__(details={"issues": issues})


def _validation_body(exc: RequestValidationError) -> dict:
    # Keep the payload small, stable, and JSON-safe: loc/msg/type per error.
    issues = [
        {
            "loc": [str(part) for part in error.get("loc", [])],
            "msg": error.get("msg", ""),
            "type": error.get("type", ""),
        }
        for error in exc.errors()
    ]
    return {
        "error": {
            "code": "validation_error",
            "message": "Request payload failed validation.",
            "details": {"issues": issues},
        }
    }


